import React, { useState, useEffect } from 'react';
import './HomePage.css';
import Header from './components/Header';
import HeroSection from './components/HeroSection';
import FeaturedMovies from './components/FeaturedMovies';
import MovieCategories from './components/MovieCategories';
import PopularMovies from './components/PopularMovies';
import Footer from './components/Footer';
import defaultDatabase from '../data/database';

function HomePage({ currentUser, onNavigate, onGoToAuth, onLogout }) {
  const [movies, setMovies] = useState([]);
  const [filteredMovies, setFilteredMovies] = useState([]);
  const [selectedGenre, setSelectedGenre] = useState('All');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    setMovies(defaultDatabase.movies || []);
    setFilteredMovies(defaultDatabase.movies || []);
  }, []);

  // Lọc phim theo thể loại
  useEffect(() => {
    let filtered = movies;

    if (selectedGenre !== 'All') {
      filtered = filtered.filter(movie => 
        movie.genre && movie.genre.includes(selectedGenre)
      );
    }

    if (searchTerm.trim()) {
      filtered = filtered.filter(movie =>
        movie.title.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    setFilteredMovies(filtered);
  }, [selectedGenre, searchTerm, movies]);

  const handleSelectMovie = (movie) => {
    onNavigate('showtime-list', movie);
  };

  const getAllGenres = () => {
    const genresSet = new Set(['All']);
    movies.forEach(movie => {
      if (movie.genre && Array.isArray(movie.genre)) {
        movie.genre.forEach(g => genresSet.add(g));
      }
    });
    return Array.from(genresSet);
  };

  return (
    <div className="home-page">
      <Header 
        currentUser={currentUser} 
        onGoToAuth={onGoToAuth}
        onLogout={onLogout}
        onNavigate={onNavigate}
      />
      
      <HeroSection 
        onNavigate={onNavigate}
      />

      <div className="homepage-content">
        {/* Search Section */}
        <section className="search-section">
          <div className="search-container">
            <input
              type="text"
              placeholder="🔍 Tìm kiếm phim yêu thích của bạn..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="search-input"
            />
          </div>
        </section>

        {/* Featured Movies */}
        <FeaturedMovies 
          movies={movies.slice(0, 4)} 
          onSelectMovie={handleSelectMovie}
        />

        {/* Movie Categories */}
        <MovieCategories 
          genres={getAllGenres()}
          selectedGenre={selectedGenre}
          onSelectGenre={setSelectedGenre}
        />

        {/* Popular Movies */}
        <PopularMovies 
          movies={filteredMovies}
          onSelectMovie={handleSelectMovie}
        />
      </div>

      <Footer />
    </div>
  );
}

export default HomePage;
